namespace StarlightSyndicateDemo;
public sealed partial class DemoWorld {
 public string FuelStructureQ(string id){var s=Organisations.Structures.FirstOrDefault(s=>s.Id==id&&s.PhysicalQ);if(s==null||Docked||s.System!=SystemId||(s.AnchorQ-SystemPosition).Length>2500||!AccessQ(s,"player","Fuel")||ItemCount("fuel",false)<10||s.State is "Destroyed" or "Recovered")return "Approach an accessible physical structure with ten fuel units.";ChangeStack("fuel",false,-10);s.Fuel+=10;if(s.State is "Low power" or "Abandoned"){s.State="Online";s.UnpoweredSince=default;}return "";}
 public string SafetyPreviewQ(SafetyWrapQ wrap,bool local=true)=>wrap.Destination.Length>0?wrap.Destination:SafetyDestinationQ(wrap,local);
 public static void ValidateSystemsQ(SaveData data){if(data.Exploration==null)return;var q=data.Exploration.SystemsQ??throw new InvalidDataException("Missing systems state.");
  bool Bad(Dictionary<string,decimal> items)=>items==null||items.Any(i=>i.Value<0||i.Value>1000000000000m||!ItemCatalog.IsSupported(i.Key));
  void Unique(IEnumerable<string> ids){var all=ids.ToArray();if(all.Any(string.IsNullOrEmpty)||all.Distinct().Count()!=all.Length)throw new InvalidDataException("Duplicate systems identity.");}
  if(q.Safety is not("Green" or "Yellow" or "Red")||q.Enlistment is not("Support" or "Oppose" or "Independent" or "Abstain")||q.NpcIndustrySinks<0||q.SupplyStock.Any(s=>s.Value<0))throw new InvalidDataException("Invalid systems policy or accounting.");
  Unique(q.Blueprints.Select(b=>b.Id));Unique(q.Jobs.Select(j=>j.Id));Unique(q.Colonies.Select(c=>c.Id));Unique(q.Launches.Select(l=>l.Id));Unique(q.Fields.Select(f=>f.Id));Unique(q.Sites.Select(s=>s.Id));Unique(q.SafetyWraps.Select(w=>w.Id));Unique(q.NpcJobs.Select(j=>j.Id));
  foreach(var b in q.Blueprints)if(!CatalogQ.Data.Activities.Any(a=>a.Blueprint==b.Type)||b.Runs<0||b.ME is <0 or >10||b.TE is <0 or >20||b.Locked!=""&&!q.Jobs.Any(j=>j.Id==b.Locked&&j.Blueprint==b.Id&&(j.State is "Active" or "Paused" or "Ready")))throw new InvalidDataException("Invalid source blueprint custody.");
  foreach(var j in q.Jobs)if(!CatalogQ.Activities.ContainsKey(j.Activity)||!q.Blueprints.Any(b=>b.Id==j.Blueprint)||j.Runs<1||j.Runs>1000||j.Fee<0||Bad(j.Inputs)||Bad(j.Outputs)||j.Copies.Any(c=>c.Value<0)||j.State is not("Active" or "Paused" or "Ready" or "Delivered" or "Cancelled" or "Lost"))throw new InvalidDataException("Invalid source job.");
  foreach(var c in q.Colonies){Unique(c.Pins.Select(p=>p.Id));if(c.Level is <0 or >5||Bad(c.Deposits))throw new InvalidDataException("Invalid colony resources.");foreach(var p in c.Pins)if(!float.IsFinite(p.X)||!float.IsFinite(p.Y)||p.X is <0 or >1||p.Y is <0 or >1||p.Heads is <1 or >10||Bad(p.Stock)||Bad(p.Pending)||p.Kind is not("Command" or "Extractor" or "Processor" or "Storage" or "Launchpad")||p.Schematic!=0&&!CatalogQ.Data.Schematics.Any(s=>s.Id==p.Schematic))throw new InvalidDataException("Invalid planetary pin.");foreach(var l in c.Links)if(l.A==l.B||l.Level is <0 or >5||!c.Pins.Any(p=>p.Id==l.A)||!c.Pins.Any(p=>p.Id==l.B))throw new InvalidDataException("Invalid planetary link.");foreach(var t in c.Routes)if(t.Rate<=0||t.Rate>100000||!ItemCatalog.IsSupported(t.Item)||!c.Links.Any(l=>l.A==t.From&&l.B==t.To||l.B==t.From&&l.A==t.To))throw new InvalidDataException("Invalid planetary route.");}
  foreach(var l in q.Launches)if(!q.Colonies.Any(c=>c.Id==l.Colony)||l.Items.Any(i=>i.Value<0||!float.IsFinite(i.Value)||!ItemCatalog.IsSupported(i.Key)))throw new InvalidDataException("Invalid physical planetary output.");
  foreach(var f in q.Fields)if(!double.IsFinite(f.Energy)||f.Energy is <0 or >100||f.Remaining<0||f.Mineable<0||f.Harvested<0||Bad(f.Output))throw new InvalidDataException("Invalid finite field.");
  foreach(var s in q.Sites)if(!double.IsFinite(s.Progress+s.Warmup+s.FuelTimer)||s.Progress is <0 or >300||s.Warmup is <0 or >60||s.Node is <0 or >2||s.State is not("Active" or "Completed" or "Failed" or "Expired")||s.Actors.Any(a=>!float.IsFinite(a.Hull)))throw new InvalidDataException("Invalid territorial objective.");
  foreach(var w in q.SafetyWraps)if(Bad(w.Items)||w.Value<0||w.Fee<0||w.State is not("Locked" or "Dropped" or "Recovered"))throw new InvalidDataException("Invalid structure safety custody.");
  foreach(var m in q.Mutations){var source=CatalogQ.Data.Mutators.FirstOrDefault(s=>s.Type==m.Mutator);if(source==null||m.Factors.Any(f=>!double.IsFinite(f.Value)||!source.Attributes.Any(a=>a.Name==f.Key&&f.Value>=a.Min&&f.Value<=a.Max))||m.Fields.Values.Any(v=>!double.IsFinite(v)||v<0))throw new InvalidDataException("Invalid sealed module mutation.");}
  foreach(var h in q.CapitalHolds.Values){if(Bad(h.Fleet)||Bad(h.Fuel))throw new InvalidDataException("Invalid capital hold.");Unique(h.Ships.Select(s=>s.Id));}
  foreach(var j in q.NpcJobs)if(Bad(j.Inputs)||j.Output<1||j.Fee<0||j.State is not("Active" or "Delivered" or "Lost"))throw new InvalidDataException("Invalid finite NPC production.");
  var structures=data.Organisations?.Structures??[];foreach(var s in structures.Where(s=>s.PhysicalQ))if(!float.IsFinite(s.ShieldQ+s.ArmorQ+s.HullQ+s.DamageUsedQ)||s.ShieldQ<0||s.ArmorQ<0||s.HullQ<0||s.StageQ is <0 or >2||s.ImmatureQ<0||s.MatureQ<0||s.HoldsQ.Values.Any(h=>Bad(h.Items)))throw new InvalidDataException("Invalid physical structure.");
  var unique=q.SafetyWraps.SelectMany(w=>w.Instances).Concat(structures.SelectMany(s=>s.HoldsQ.Values).SelectMany(h=>h.Instances)).Concat(data.Commander?.Wrecks.SelectMany(w=>w.Instances)??[]).Concat(data.Commander?.Contracts.SelectMany(c=>c.Instances)??[]).Concat(data.Commander?.Containers.SelectMany(c=>c.Instances)??[]);Unique(unique.Select(i=>i.Id));
 }
}
